class Solution {
public:
    int longestDecomposition(string text) {
        int left = 0, right = text.size() - 1;
        string l_str = "", r_str = "";
        int count = 0;
        while (left < right) {
            l_str += text[left];
            r_str = text[right] + r_str;
            if (l_str == r_str) {
                count += 2;
                l_str = "";
