            count++;
        }
        return count;
    }
};

class Solution {
    public int longestDecomposition(String text) {
        int left = 0, right = text.length() - 1;
        StringBuilder lStr = new StringBuilder();
        StringBuilder rStr = new StringBuilder();
        int count = 0;
        while (left < right) {
            lStr.append(text.charAt(left));
            rStr.insert(0, text.charAt(right));
            if (lStr.toString().equals(rStr.toString())) {
                count += 2;
                lStr.setLength(0);
                rStr.setLength(0);
            }
            left++;
            right--;
        }
        if (left == right || lStr.length() > 0) {
            count++;
        }
        return count;
    }
}

